entries[122529] = { ["name"] = "Dread Pirate Ring", ["text"] = "Heirloom Upgrade Level: 0/0\nBinds to Warband\nUnique-Equipped\nFinger\n+9 Stamina\n+ 18 Critical Strike\n+ 10 Haste\nRequires level 1 to 29 ( 29)\n\nRegalia of Fabled Adventurers (0/7)\nHeirloom Chestpiece\nHeirloom Helm\nHeirloom Shoulders\nHeirloom Cloak\nHeirloom Legs\nHeirloom Necklace\nHeirloom Ring\n(2) Set : Rested experience consumed is reduced by 30%.\n(3) Set : Increases your out-of-combat regeneration in the outdoors, normal dungeons and battlegrounds.\n(5) Set : Gaining a level triggers Burst of Knowledge, dealing 1126 Holy damage to nearby enemies and granting you 40% Primary Stat for 2 min. Defeating enemies extends this effect, up to an additional 2 min.\n(6) Set : Rested experience consumed is reduced by an additional 30%.\n\nQuest:\nStranglethorn Fishing Extravaganza" }
entries[122530] = { ["name"] = "Inherited Mark of Tyranny", ["text"] = "Heirloom Upgrade Level: 0/0\nBinds to Warband\nUnique\nTrinket\n+11 Stamina\nUse: Increases maximum health by 1057 for 15 sec. Shares cooldown with other Battlemaster's trinkets. (2 Min Cooldown)\nRequires level 1 to 29 ( 29)\n\nVendor:\nEstelle Gendry\nZone:\nOrgrimmar - Gates of Orgrimmar\n\nVendor:\nKrom Stoutarm\nZone:\nIronforge - Hall of Explorers" }
