entries[122674] = { ["name"] = "S.E.L.F.I.E. Camera MkII", ["text"] = "Binds when picked up\nToy\nUse: Frame the perfect shot and take a selfie! (2 Sec Cooldown)\n\"Who doesn't like a selfie every now and then?\"" }
entries[122677] = { ["name"] = "Bag of Gold", ["text"] = "Binds when picked up\nUnique\nUse: Open the bag." }
entries[122679] = { ["name"] = "Vrykul Weapon", ["text"] = "Quest Item\n\"A weapon from a less civilized age.\"" }
entries[122681] = { ["name"] = "Sternfathom's Pet Journal", ["text"] = "Binds when picked up\nToy\nUse: Open the book. Only usable in Azsuna. (2 Min Cooldown)\n\"Authored by slaves, this journal lists the strengths, weaknesses and skills of Sternfathom's collection of gladiators.\"" }
