entries[122686] = { ["name"] = "Oiled Cloak", ["text"] = "Quest Item" }
entries[122696] = { ["name"] = "Sea Scorpion Lunker", ["text"] = "Binds when picked up\n\"Careful. It could take off one of your fingers with its pincers. Only caught by masterful anglers with the help of Nat Pagle.\"" }
entries[122699] = { ["name"] = "Okuna's Message", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 10 to 45 ( 45)\n\"The note in this bottle contains a plea for help from someone named, Okuna Longtusk. Apparently, he and his fellow shipmates are being held as slaves by a clan of sea giants.\"" }
entries[122700] = { ["name"] = "Portable Audiophone", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Put down your Portable Audiophone. (1 Min Cooldown)\n\"A tiny music player, magically attuned to its owner.\"" }
entries[122701] = { ["name"] = "High Explosive Grenades", ["text"] = "Quest Item" }
entries[122702] = { ["name"] = "Containment Unit", ["text"] = "Quest Item" }
entries[122703] = { ["name"] = "Chauffeured Chopper", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nHire a Chauffeur to drive you around.\n\"Hire your personal chauffeur.\"\n\n\"Why drive yourself around when you can hire someone to do it for you?\"\nAchievement:\nHeirloom Hoarder" }
entries[122704] = { ["name"] = "Elothir's Branch", ["text"] = "Quest Item\nUse: Removes the curse of stone from petrified creatures in Thas'talah. (6 Sec Cooldown)" }
entries[122705] = { ["name"] = "Plans: Riddle of Truesteel", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to forge a Truesteel Ingot without rest.\nRequires Draenor Blacksmithing (1)\n\nTruesteel Ingot\nBinds when picked up\nCrafting Reagent\nSell Price:\nRequires Primal Spirit , True Iron Ore (5), Blackrock Ore (5)" }
entries[122706] = { ["name"] = "Primal Gladiator's Medallion of Adaptation", ["text"] = "Warlords Season 1\nBinds when picked up\nUnique-Equipped\nTrinket\n+ 11 Versatility\nRequires any Alliance race\nUse: Removes all movement impairing effects and all effects which cause loss of control of your character. (2 Min Cooldown)\nSell Price:" }
