entries[122710] = { ["name"] = "Recipe: Primal Alchemy", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft Alchemical Catalyst without rest.\nRequires Draenor Alchemy (1)\n\nAlchemical Catalyst\nCrafting Reagent\n\"Catalyzes reactions that would otherwise take thousands of years, making it essential to the Alchemy of Draenor.\"\nRequires Primal Spirit , Fireweed (2), Gorgrond Flytrap (2), Nagrand Arrowbloom (2), Starflower (2), Talador Orchid (2)" }
entries[122711] = { ["name"] = "Formula: Temporal Binding", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to create Fractured Temporal Crystals without rest.\nRequires Draenor Enchanting (1)\n\nFractured Temporal Crystal\nUse: Combine 10 fractured temporal crystals into one temporal crystal.\nCrafting Reagent\nRequires Primal Spirit , Luminous Shard" }
entries[122712] = { ["name"] = "Schematic: Primal Welding", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Gearspring Parts without rest.\nRequires Draenor Engineering (1)\n\nGearspring Parts\nBinds when picked up\nCrafting Reagent\n\"The ultimate in adaptability, these parts are revered by engineers creating or fixing complex devices.\"\nSell Price:\nRequires Primal Spirit , Blackrock Ore (5), True Iron Ore (5)" }
entries[122713] = { ["name"] = "Technique: The Spirit of War", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft War Paints without rest.\nRequires Draenor Inscription (1)\nSell Price:\nWar Paints\nBinds when picked up\nCrafting Reagent\nRequires Primal Spirit , Cerulean Pigment (4)" }
entries[122714] = { ["name"] = "Design: Primal Gemcutting", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make a Taladite Crystal without rest.\nRequires Draenor Jewelcrafting (1)\n\nTaladite Crystal\nBinds when picked up\nCrafting Reagent\n\"A versatile synthetic gem, used in many Draenor jewelcrafting recipes.\"\nRequires Primal Spirit , Blackrock Ore (5), True Iron Ore (5)" }
entries[122715] = { ["name"] = "Pattern: Spiritual Leathercraft", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to make Burnished Leather without rest.\nRequires Draenor Leatherworking (1)\n\nBurnished Leather\nBinds when picked up\nCrafting Reagent\n\"Both tough and supple, used in Leatherworking in Draenor.\"\nSell Price:\nRequires Primal Spirit , Raw Beast Hide (10)" }
entries[122716] = { ["name"] = "Pattern: Primal Weaving", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to weave Hexweave Cloth without rest.\nRequires Draenor Tailoring (1)\n\nHexweave Cloth\nBinds when picked up\nCrafting Reagent\n\"Fur woven into fine cloth. The basis for most Tailoring in Draenor.\"\nSell Price:\nRequires Primal Spirit , Sumptuous Fur (10)" }
