entries[122742] = { ["name"] = "Bladebone Hook", ["text"] = "Use: Applies a razor sharp barb to your fishing pole for 1 hour, automatically filleting any Draenor fish you catch.\nRequires Fishing (50)\nSell Price:" }
entries[122743] = { ["name"] = "Gaiju Pearl", ["text"] = "Binds when picked up\nUse: Gaze deep in to the reflection in the pearl. Only usable underwater in Draenor. (30 Min Cooldown)" }
