entries[124072] = { ["name"] = "Ward of Sargeras", ["text"] = "Binds when picked up\nUnique\nUse: Regenerates 2% health every 5 sec and reduces all damage taken by 10% for 10 min. Does not work on players over level 49. (5 Min Cooldown)\n\"Protection.\"" }
entries[124073] = { ["name"] = "Flare Launcher", ["text"] = "Binds when picked up\nUnique (3)\nUse: Call in a reinforcement of Gryphon Riders from the skies. (3 Sec Cooldown)\n\"Call in the troops!\"" }
entries[124075] = { ["name"] = "Illidari Warglaives [update icon]", ["text"] = "Quest Item\n\"The edge is still as deadly as the last day you sharpened them at the Black Temple, eight years ago.\"" }
