entries[124089] = { ["name"] = "Vicious War Mechanostrider", ["text"] = "Binds to Warband\nMount\nRequires any Alliance race\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Equipped with head-mounted Critter Destroyer 9000.\"\nVendor:\nNecrolord Sipe\nZone:\nStormwind City\nCost:\n1" }
entries[124093] = { ["name"] = "Minor Blackfang Challenge Totem", ["text"] = "Binds when picked up\nUse: Challenge a minor champion of the Blackfang at the arena in Fang'rila. (10 Sec Cooldown)\n\"Used in the Blackfang fighting rituals to challenge a saberon champion.\"" }
