entries[124154] = { ["name"] = "Gloves of the Arcanic Conclave", ["text"] = "Binds when picked up\nHands Cloth\n2 Armor\n+3 Intellect\n+5 Stamina\n+ 2 Critical Strike\n+ 4 Haste\nDurability 55 / 55\nClasses: Mage\nRaiment of the Arcanic Conclave (0/5)\nGloves of the Arcanic Conclave\nCowl of the Arcanic Conclave\nPantaloons of the Arcanic Conclave\nRobe of the Arcanic Conclave\nMantle of the Arcanic Conclave\nLegacy Set: Bonus is inactive\n(2) Set Arcane: Arcane Missiles has a 35% chance to create a Time Anomaly, summoning a random hero through time to assist you in battle for 10 sec. (Proc chance: 35%)\n(2) Set Fire: Pyroblast has a 25% chance to conjure a Fiery Phoenix, dealing Fire damage to the target. (Proc chance: 25%)\n(2) Set Frost: Water Jet automatically activates Brain Freeze.\n(4) Set Arcane: Each of the heroes summoned by Time Anomaly increases the damage you deal by 12% until it departs.\n(4) Set Fire: When the phoenix is summoned, you gain 6% spell damage and 6% spell haste for 15 sec.\n(4) Set Frost: Increases the duration of Water Jet by 10 sec, and increases the maximum number of Fingers of Frost charges by 2.\nSell Price:" }
entries[124155] = { ["name"] = "Pious Handwraps", ["text"] = "Binds when picked up\nHands Cloth\n2 Armor\n+3 Intellect\n+5 Stamina\n+ 3 Critical Strike\n+ 4 Mastery\nDurability 55 / 55\nClasses: Priest\nAttire of Piety (0/5)\nPious Handwraps\nPious Cowl\nPious Leggings\nPious Raiment\nPious Mantle\nLegacy Set: Bonus is inactive\n(2) Set Discipline: Your Penance damage and healing is increased by 4% for 15 sec each time it deals damage or heals. This effect stacks up to 6 times.\n(2) Set Holy: You gain 2% haste for 15 sec when Prayer of Mending bounces. This effect can stack up to 3 times.\n(2) Set Shadow: Reduces the cooldown on Shadowfiend by 30 sec and the cooldown on Mindbender by 10 sec.\n(4) Set Discipline: Each time Penance heals or damages, it has a 50% chance to heal another injured ally near your target.\n(4) Set Holy: Your Prayer of Mending has a 10% chance to split when it bounces, healing an additional target nearby.\n(4) Set Shadow: When your Shadowfiend or Mindbender expires, you gain Premonition, increasing your Critical Strike, Haste, and Mastery ratings by 108 for 15 sec.\nSell Price:" }
entries[124156] = { ["name"] = "Deathrattle Gloves", ["text"] = "Binds when picked up\nHands Cloth\n2 Armor\n+3 Intellect\n+5 Stamina\n+ 2 Haste\n+ 4 Mastery\nDurability 55 / 55\nClasses: Warlock\nDeathrattle Regalia (0/5)\nDeathrattle Gloves\nDeathrattle Mask\nDeathrattle Leggings\nDeathrattle Robe\nDeathrattle Shoulderpads\nLegacy Set: Bonus is inactive\n(2) Set Affliction: Each time Drain Life or Drain Soul deals damage, it has a 10% chance to make your next Unstable Affliction not consume a Soul Shard. (Proc chance: 10%)\n(2) Set Demonology: Your Shadow Bolt increases the damage done by your Demons by 1% for 15 sec. This effect can stack up to 5 times.\n(2) Set Destruction: Reduces the cast time of your Chaos Bolt by 0.5 sec and increases its damage by 2%.\n(4) Set Affliction: When Unstable Affliction deals damage, you have a 10% chance to gain 10% increased damage for 5 sec. (Proc chance: 10%)\n(4) Set Demonology: When your Wild Imps cast Felfire Bolt, you have a 2% chance to summon a Demon from the void to assist you in battle.\n(4) Set Destruction: Your Chaos Bolt has a 12% chance to not consume a Soul Shard.\nSell Price:" }
