entries[124246] = { ["name"] = "Oathclaw Vestment", ["text"] = "Binds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 6 Haste\n+ 3 Mastery\nDurability 165 / 165\nClasses: Druid\nOathclaw Wargarb (0/5)\nOathclaw Vestment\nOathclaw Gauntlets\nOathclaw Helm\nOathclaw Leggings\nOathclaw Mantle\nLegacy Set: Bonus is inactive\n(2) Set Balance: Your Moonfire and Sunfire have a chance to summon a Faerie Dragon to assist you in battle for 30 sec.\n(2) Set Feral: Increases the chance for Omen of Clarity to trigger, and increases your maximum Energy while in Cat Form by 20.\n(2) Set Guardian: Ironfur also increases heals done to you by 20% while active.\n(2) Set Restoration: Your Lifebloom has a 5% chance to bloom when it periodically heals.\n(4) Set Balance: When a Faerie Dragon is summoned, your Arcane and Nature damage is increased by 6% for 30 sec.\n(4) Set Feral: During Omen of Clarity, your next Cat Form ability generates 100% of its Energy cost when used.\n(4) Set Guardian: While Ironfur is active, the cost of Frenzied Regeneration is reduced by 50%.\n(4) Set Restoration: You can Lifebloom two targets at once.\nSell Price:" }
entries[124247] = { ["name"] = "Robe of the Hurricane's Eye", ["text"] = "Binds when picked up\nChest Leather\n8 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 3 Critical Strike\n+ 6 Mastery\nDurability 165 / 165\nClasses: Monk\nBattlewrap of the Hurricane's Eye (0/5)\nRobe of the Hurricane's Eye\nFistwraps of the Hurricane's Eye\nMask of the Hurricane's Eye\nLegwraps of the Hurricane's Eye\nMantle of the Hurricane's Eye\nLegacy Set: Bonus is inactive\n(2) Set Brewmaster: Increases the chance to for your Gift of the Ox to summon a Healing Sphere by 2%.\n(2) Set Windwalker: Your Rising Sun Kick grants 2 charges of Masterful Strikes. Masterful Strikes increases mastery by 10% on your next damaging abilitiy.\n(2) Set Mistweaver: Your Renewing Mist also applies Extend Life to the initial target, instantly healing them for (26.45% of Spell Power) and increasing all healing done to them by 15% for 12 sec.\n(4) Set Brewmaster: Every time you gather a Healing Sphere, the remaining cooldowns of your Ironskin Brew and Purifying Brew are reduced by 1 sec.\n(4) Set Windwalker: Your Fists of Fury grants 3 charges of Masterful Strikes, and increases your maximum Energy by 20.\n(4) Set Mistweaver: When you heal with Enveloping Mist or Vivify, 50% of the heal is also applied to targets with your Extend Life effect.\nSell Price:" }
