entries[124317] = { ["name"] = "Demongaze Chestplate", ["text"] = "Binds when picked up\nChest Plate\n17 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 4 Critical Strike\n+ 5 Mastery\nDurability 165 / 165\nClasses: Death Knight\nDemongaze Armor (0/5)\nDemongaze Chestplate\nDemongaze Gauntlets\nDemongaze Helm\nDemongaze Legplates\nDemongaze Pauldrons\nLegacy Set: Bonus is inactive\n(2) Set Blood: Heart Strike has a 25% chance to generate an extra 10 Runic Power.\n(2) Set Frost: When you critically hit with Obliterate you gain 3% haste for 12 sec. When you critically hit with Frost Strike, your critical damage is increased by 6% for 12 sec.\n(2) Set Unholy: Increases the damage dealt by your pets by 20%.\n(4) Set Blood: Reduces the cost of Death Strike by 5 Runic Power.\n(4) Set Frost: Obliterate and Frostscythe have a 65% chance not to consume Killing Machine.\n(4) Set Unholy: Your Dark Transformation now transforms your [ Sludge Belcher : Abomination / Ghoul] into a Crazed Monstrosity, increasing both the Monstrosity's and your damage and attack speed.\nSell Price:" }
entries[124318] = { ["name"] = "Cuirass of the Ceaseless Vigil", ["text"] = "Binds when picked up\nChest Plate\n17 Armor\n+5 [Strength or Intellect]\n+7 Stamina\n+ 3 Critical Strike\n+ 6 Mastery\nDurability 165 / 165\nClasses: Paladin\nWatch of the Ceaseless Vigil (0/5)\nCuirass of the Ceaseless Vigil\nGauntlets of the Ceaseless Vigil\nHelm of the Ceaseless Vigil\nGreaves of the Ceaseless Vigil\nShoulderplates of the Ceaseless Vigil\nLegacy Set: Bonus is inactive\n(2) Set Holy: Increases the amount of healing transferred to your Beacon of Light targets by 25%.\n(2) Set Protection: When you cast Avenger's Shield, you gain an absorb effect equal to 5.0% of your maximum health for 10 sec.\n(2) Set Retribution: Increases all damage you do by 2%.\n(4) Set Holy: Your spell haste is increased by 2% every time you heal your Beacon of Light target. Lasts for 6 sec. Stacks up to 4 times.\n(4) Set Protection: Your Avenger's Shield has a 50% chance to have it's cooldown instantly reset when used. (Proc chance: 50%)\n(4) Set Retribution: After using Avenging Wrath, your damage is increased by 5% every 1 sec for 10 sec.\nSell Price:" }
